halId = "claire-morel"   // ← remplacez par votre idHAL

// Interroge HAL pour un type de document donné
async function halFetch(filtre) {
  const params = new URLSearchParams({
    q: `authIdHal_s:${halId}`,
    fq: filtre,
    fl: "citationFull_s,producedDateY_i",
    sort: "producedDateY_i desc",
    rows: "500",
    wt: "json"
  });
  try {
    const r = await fetch("https://api.archives-ouvertes.fr/search/?" + params);
    const j = await r.json();
    return j.response.docs;
  } catch (e) {
    return null;
  }
}

// Affiche la liste, regroupée par année
function halRender(docs, messageVide) {
  if (docs === null)
    return html`&lt;p&gt;&lt;em&gt;Impossible de joindre HAL pour le moment.
      Consultez directement &lt;a href="https://cv.hal.science/${halId}"&gt;mon CV HAL&lt;/a&gt;.&lt;/em&gt;&lt;/p&gt;`;
  if (docs.length === 0)
    return html`&lt;p&gt;&lt;em&gt;${messageVide}&lt;/em&gt;&lt;/p&gt;`;

  const conteneur = html`&lt;div class="hal-liste"&gt;&lt;/div&gt;`;
  const annees = [...new Set(docs.map(d =&gt; d.producedDateY_i))];
  for (const a of annees) {
    conteneur.append(html`&lt;p&gt;&lt;strong&gt;${a}&lt;/strong&gt;&lt;/p&gt;`);
    const ul = html`&lt;ul&gt;&lt;/ul&gt;`;
    for (const d of docs.filter(d =&gt; d.producedDateY_i === a)) {
      const li = document.createElement("li");
      li.innerHTML = d.citationFull_s;
      ul.append(li);
    }
    conteneur.append(ul);
  }
  return conteneur;
}
























